#!/usr/bin/env python3
"""HTTP server for the duty-roster planner - server-compute variant.

Serves the prebuilt UI from server_static/ and computes rosters ON THE SERVER with
the same Python engine the browser (Pyodide) variant uses: public/roster_engine.py.
Python standard library only - no dependencies to install.

Privacy: the input (names/nicknames, leave days, tasks) arrives over HTTPS, is used
only for the computation and the immediate response, and is never written to disk.
Logs carry aggregate metadata only (counts, timings) - never input content.
"""
import base64
import gzip
import json
import logging
import os
import sys
import math
import multiprocessing
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / 'public'))
import roster_engine  # noqa: E402

PORT = int(os.environ.get('PORT', '8000'))
STATIC_DIR = ROOT / 'server_static'
# Generated from npm run build. Embedded compressed UI avoids a Node build at deployment.
EMBEDDED_UI = {'/index.html': '', '/assets/index-kAmw6x3P.css': '', '/assets/index-BdNR7Lf4.js': ''}

MAX_BODY = 256 * 1024
MAX_PEOPLE = 200
MAX_TASKS = 100
MAX_NAME = 60
MAX_DAYS = 31
MAX_ITERATIONS = 80000
SOLVE_SLOTS = threading.BoundedSemaphore(2)  # free instance: keep health/static responsive

CONTENT_TYPES = {
    '.html': 'text/html; charset=utf-8',
    '.js': 'text/javascript; charset=utf-8',
    '.mjs': 'text/javascript; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.svg': 'image/svg+xml',
    '.png': 'image/png',
    '.ico': 'image/x-icon',
    '.woff2': 'font/woff2',
}

logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')
log = logging.getLogger('roster-server')


def err(message):
    return 400, {'error': message}, None, None, None


def validate_payload(d):
    """Reject invalid data rather than silently changing scheduling intent."""
    try:
        def number(x, lo, hi, integer=False):
            if isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) or not lo <= x <= hi or (integer and int(x) != x):
                raise ValueError('numeric bounds')
            return int(x) if integer else x
        def name(x):
            if not isinstance(x, str) or not x.strip() or len(x) > MAX_NAME:
                raise ValueError('name')
            return x.strip()
        def days(x, hi):
            if not isinstance(x, list) or len(x) > 62:
                raise ValueError('days')
            return [number(v, 0, hi, True) for v in x]
        if not isinstance(d, dict) or not isinstance(d.get('maxRest'), bool):
            raise ValueError('payload')
        cfg, people, tasks = d['cfg'], d['people'], d['tasks']
        if not isinstance(cfg, dict) or not isinstance(people, list) or not isinstance(tasks, list) or not 1 <= len(people) <= MAX_PEOPLE or not 1 <= len(tasks) <= MAX_TASKS:
            raise ValueError('shape/count')
        c = {k: number(cfg[k], lo, hi, integer) for k, lo, hi, integer in [
            ('days', 1, MAX_DAYS, True), ('minRest', 0, 72, False),
            ('comfortRest', 0, 96, False), ('balance', 0, 1, False),
            ('firstWeekday', 0, 6, True), ('seed', 0, 2**31, True),
            ('iterations', 1, MAX_ITERATIONS, True)]}
        c['weekendDays'] = days(cfg['weekendDays'], 6)
        ppl = [{'name': name(p['name']), 'leave': days(p.get('leave', []), c['days']-1)} for p in people]
        tsk = []
        for t in tasks:
            nt = {'name': name(t['name']), 'req': number(t['req'], 1, 10, True),
                  'from': number(t['from'], 0, 23.999999), 'to': number(t['to'], 0, 48),
                  'shiftLen': number(t['shiftLen'], .5, 24),
                  'restBefore': number(t.get('restBefore', 0), 0, 72),
                  'restAfter': number(t.get('restAfter', 0), 0, 72)}
            if nt['to'] > 24 and nt['to'] != nt['from'] + 24:
                raise ValueError('window')
            if t.get('days') is not None:
                nt['days'] = days(t['days'], c['days']-1)
            tsk.append(nt)
        slots = roster_engine.build_slots(c, tsk)
        if len(slots) > 2000 or sum(tsk[x['task']]['req'] for x in slots) > 5000:
            raise ValueError('schedule too large')
        return 200, c, ppl, tsk, d['maxRest']
    except (ValueError, TypeError, KeyError, OverflowError):
        return err('קלט לא תקין או גדול מדי. עד 31 ימים, 200 אנשים, 100 משימות ו-2000 משמרות; שמות עד 60 תווים. בדקו גם את ימי ההיעדרות והמשימות.')


def compute(conn, cfg, people, tasks, max_rest):
    try:
        r = roster_engine.solve_max_rest(cfg, people, tasks) if max_rest else roster_engine.solve(cfg, people, tasks)
        r = roster_engine._clean(r)
        r['engine'] = 'python-server'
        conn.send(r)
    except Exception:
        conn.send(None)
    finally:
        conn.close()


class Handler(BaseHTTPRequestHandler):
    def setup(self):
        super().setup()
        self.connection.settimeout(15)

    server_version = 'roster-server/1.0'
    protocol_version = 'HTTP/1.1'

    def log_message(self, fmt, *args):  # metadata only, no bodies
        pass  # No request paths, IPs or user-controlled text in application logs

    def _send(self, status, body, ctype='application/json; charset=utf-8', extra=None):
        data = body if isinstance(body, bytes) else body.encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', ctype)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Referrer-Policy', 'no-referrer')
        self.send_header('Content-Security-Policy', "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'")
        if extra:
            for k, v in extra.items():
                self.send_header(k, v)
        self.end_headers()
        if self.command != 'HEAD':
            self.wfile.write(data)

    def _json(self, status, obj):
        self._send(status, json.dumps(obj, ensure_ascii=False))

    def do_GET(self):
        self._route(head=True)

    def do_HEAD(self):
        self._route(head=True)

    def _route(self, head=False):
        path = self.path.split('?', 1)[0].split('#', 1)[0]
        if path == '/api/health':
            self._json(200, {'ok': True, 'engine': 'python-server'})
            return
        if path == '/':
            path = '/index.html'
        packed = EMBEDDED_UI.get(path)
        if packed is None:
            self._json(404, {'error': 'not found'})
            return
        ctype = CONTENT_TYPES.get(Path(path).suffix.lower(), 'application/octet-stream')
        self._send(200, gzip.decompress(base64.b64decode(packed)), ctype)

    def do_POST(self):
        path = self.path.split('?', 1)[0]
        if path != '/api/solve':
            self._json(404, {'error': 'not found'})
            return
        try:
            length = int(self.headers.get('Content-Length') or 0)
        except ValueError:
            length = 0
        if length <= 0 or length > MAX_BODY:
            self._json(413, {'error': 'גוף הבקשה גדול מדי או חסר'})
            return
        try:
            d = json.loads(self.rfile.read(length))
        except (json.JSONDecodeError, UnicodeDecodeError):
            self._json(400, {'error': 'גוף הבקשה אינו JSON תקין'})
            return
        status, cfg, people, tasks, max_rest = validate_payload(d)
        if status != 200:
            self._json(status, cfg)  # cfg holds {'error': ...} here
            return
        if not SOLVE_SLOTS.acquire(blocking=False):
            self._json(429, {'error': 'השרת עסוק כרגע, נסו שוב בעוד כמה שניות'})
            return
        t0 = time.monotonic()
        try:
            ctx = multiprocessing.get_context('spawn')
            parent, child = ctx.Pipe(duplex=False)
            proc = ctx.Process(target=compute, args=(child, cfg, people, tasks, max_rest))
            proc.start()
            child.close()
            try:
                if not parent.poll(45):
                    self._json(503, {'error': 'החישוב חרג מ-45 שניות. צמצמו ימים או משימות ונסו שוב.'})
                    return
                res = parent.recv()
                if res is None:
                    raise RuntimeError('compute failed')
            finally:
                if proc.is_alive():
                    proc.terminate()
                proc.join(timeout=2)
                parent.close()
            elapsed = time.monotonic() - t0
            # aggregate metadata only - never names or content
            log.info('solve ok: people=%d tasks=%d days=%d iters=%d feasibility=%s elapsed=%.2fs',
                     len(people), len(tasks), cfg['days'], cfg['iterations'], res.get('feasibility'), elapsed)
            self._json(200, res)
        except Exception:
            log.error('solve failed')
            self._json(500, {'error': 'החישוב בשרת נכשל. נסו לפשט את הקלט או לנסות שוב.'})
        finally:
            SOLVE_SLOTS.release()


if __name__ == '__main__':
    if not STATIC_DIR.is_dir():
        log.warning('server_static/ is missing - the UI will 404 until it is built')
    log.info('listening on 0.0.0.0:%d', PORT)
    ThreadingHTTPServer(('0.0.0.0', PORT), Handler).serve_forever()
